VALUES
('Bubur Singkong Isi Ikan dan Ayam dengan Saus Jeruk', 'bubur-singkong-isi-ikan-ayam-saus-jeruk', NULL, 6, 8, 'sedang', 'Mulai 2-3 sdm per makan, bertahap hingga 1/2 mangkok (125 ml) · resep untuk 3 porsi', '2-3 kali/hari makan utama, 1-2 kali/hari selingan', '{"per": "1 porsi", "calories": 91, "calories_kcal": 91, "protein_g": 3.1, "fat_g": 3.5, "carbs_g": 11.8, "iron_mg": 0.4, "iron_coverage_pct": 100.0, "texture": "Bubur kental / makanan lumat", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (USDA SR28), batas bawah"}}'::jsonb, ARRAY['75 g singkong putih, rebus dan haluskan','15 g (2 sdm datar) daging ikan kembung cincang halus','15 g daging ayam cincang rebus','250 ml air kaldu ayam','5 g (1 sdt) minyak kelapa','20 g (2 sdm) bayam segar, potong halus','1 lembar daun salam, 1 batang sereh','Bumbu halus: 1 siung bawang merah, 1 siung bawang putih','100 g (3 buah kecil) jeruk manis, diambil sarinya']::text[], ARRAY['ikan']::text[], '[{"step": 1, "text": "Tumis bumbu halus, masukkan daun salam dan sereh."}, {"step": 2, "text": "Tambahkan kaldu, singkong, ikan, dan ayam; masak setengah matang."}, {"step": 3, "text": "Masukkan bayam hingga matang, lalu saring atau blender sesuai tekstur."}, {"step": 4, "text": "Beri sari jeruk sesaat sebelum disajikan."}]'::jsonb, 'Kemenkes RI (2023). Makanan Lokal Bayi, Balita dan Ibu Hamil: Buku Resep. Jakarta: Kementerian Kesehatan RI. hlm. 11', 'Belum divalidasi ahli gizi Nutriva', 'https://eprints.poltekkesadisutjipto.ac.id/id/eprint/1953/1/Share%20Buku%20Menu%20Makanan%20Lokal.pdf', NULL),
('Bubur Soto Ayam Santan', 'bubur-soto-ayam-santan', NULL, 6, 8, 'sedang', 'Mulai 2-3 sdm per makan, bertahap hingga 1/2 mangkok (125 ml) · resep untuk 3 porsi', '2-3 kali/hari makan utama, 1-2 kali/hari selingan', '{"per": "1 porsi", "calories": 96, "calories_kcal": 96, "protein_g": 4.6, "fat_g": 4.1, "carbs_g": 10.2, "iron_mg": 1.0, "iron_coverage_pct": 100.0, "texture": "Bubur kental / makanan lumat", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (USDA SR28), batas bawah"}}'::jsonb, ARRAY['60 g (6 sdm) nasi putih','45 g (4,5 sdm) daging ayam cincang','30 g (1 buah kecil) tahu','30 g (3 sdm) labu siam','15 g (1,5 sdm) wortel','1 lembar salam, 1 batang sereh, 1 lembar daun jeruk','5 g minyak goreng','30 ml (3 sdm) santan','300 ml air kaldu ayam','Bumbu halus: 1 siung bawang merah, 1 siung bawang putih, 1 cm kunyit, 1 cm jahe','100 g (3 buah kecil) jeruk, diambil sarinya']::text[], ARRAY['kedelai']::text[], '[{"step": 1, "text": "Tumis bumbu halus dan ayam hingga berubah warna."}, {"step": 2, "text": "Tambahkan kaldu, santan, dan rempah daun; didihkan."}, {"step": 3, "text": "Masukkan nasi, tahu, labu siam, dan wortel hingga empuk."}, {"step": 4, "text": "Haluskan sesuai tekstur usia dan sajikan hangat dengan sari jeruk."}]'::jsonb, 'Kemenkes RI (2023). Makanan Lokal Bayi, Balita dan Ibu Hamil: Buku Resep. Jakarta: Kementerian Kesehatan RI. hlm. 12', 'Belum divalidasi ahli gizi Nutriva', 'https://eprints.poltekkesadisutjipto.ac.id/id/eprint/1953/1/Share%20Buku%20Menu%20Makanan%20Lokal.pdf', NULL),
('Bubur Sup Daging Kacang Merah', 'bubur-sup-ayam-kacang-merah', NULL, 6, 8, 'sedang', 'Mulai 2-3 sdm per makan, bertahap hingga 1/2 mangkok (125 ml) · resep untuk 3 porsi', '2-3 kali/hari makan utama, 1-2 kali/hari selingan', '{"per": "1 porsi", "calories": 83, "calories_kcal": 83.2, "protein_g": 4.9, "fat_g": 2.1, "carbs_g": 11.5, "iron_mg": 0.6, "iron_coverage_pct": 100.0, "texture": "Bubur kental / makanan lumat", "basis": {"energy_protein_fat": "estimasi dari bahan (USDA SR28); nilai tercetak tidak plausibel", "carbs": "estimasi dari bahan (USDA SR28)", "iron": "estimasi dari bahan bergramasi (USDA SR28), batas bawah"}}'::jsonb, ARRAY['50 g (6 sdm) nasi','30 g (3 sdm) daging ayam cincang','25 g (1/2 butir) telur ayam','10 g (1 sdm) buncis','10 g (1 sdm) wortel','10 g (1 sdm) kacang merah','10 g (1 batang) bawang daun','1 batang seledri','300 ml kaldu ayam','2,5 g (1/2 sdt) minyak untuk menumis','Bumbu halus: 2 siung bawang merah, 2 siung bawang putih','100 g (2 buah) jeruk, diambil sarinya']::text[], ARRAY['telur']::text[], '[{"step": 1, "text": "Rebus kacang merah dalam kaldu hingga empuk."}, {"step": 2, "text": "Tumis bumbu halus dan ayam, lalu masukkan ke dalam kaldu."}, {"step": 3, "text": "Tambahkan nasi, buncis, dan wortel; masukkan telur kocok sambil diaduk hingga matang."}, {"step": 4, "text": "Haluskan sesuai tekstur usia dan sajikan dengan sari jeruk."}]'::jsonb, 'Kemenkes RI (2023). Makanan Lokal Bayi, Balita dan Ibu Hamil: Buku Resep. Jakarta: Kementerian Kesehatan RI. hlm. 13', 'Belum divalidasi ahli gizi Nutriva', 'https://eprints.poltekkesadisutjipto.ac.id/id/eprint/1953/1/Share%20Buku%20Menu%20Makanan%20Lokal.pdf', 'Judul menyebut ''daging'' tetapi bahan tercetak adalah daging ayam. Protein tercetak 45,1 g tidak mungkin untuk 98 kkal (salah cetak).'),
('Bubur Kanju Rumbi Ayam dan Udang', 'bubur-kanju-rumbi-ayam-udang', NULL, 6, 8, 'premium', 'Mulai 2-3 sdm per makan, bertahap hingga 1/2 mangkok (125 ml) · resep untuk 3 porsi', '2-3 kali/hari makan utama, 1-2 kali/hari selingan', '{"per": "1 porsi", "calories": 87, "calories_kcal": 87, "protein_g": 5.1, "fat_g": 2.9, "carbs_g": 10.1, "iron_mg": 0.3, "iron_coverage_pct": 100.0, "texture": "Bubur kental / makanan lumat", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (USDA SR28), batas bawah"}}'::jsonb, ARRAY['60 g (6 sdm) nasi putih','30 g (3 sdm) daging ayam bagian dada','20 g udang segar','15 g wortel','15 g jagung pipil','15 ml santan','350 ml kaldu ayam','2 lembar daun pandan','Bumbu halus: bawang merah, bawang putih, kapulaga, ketumbar, kayu manis, cengkeh, merica, jintan, adas, pekak, pala','50 g (6 potong kecil) pepaya']::text[], ARRAY['udang/krustasea']::text[], '[{"step": 1, "text": "Rebus ayam setengah matang, potong dadu; rebus udang di air yang sama, kupas dan potong."}, {"step": 2, "text": "Tumis bumbu halus dan daun pandan, tambahkan kaldu dan nasi hingga lembek."}, {"step": 3, "text": "Masukkan ayam, udang, wortel, dan jagung; masak hingga matang."}, {"step": 4, "text": "Saring sesuai tekstur usia dan sajikan dengan pepaya."}]'::jsonb, 'Kemenkes RI (2023). Makanan Lokal Bayi, Balita dan Ibu Hamil: Buku Resep. Jakarta: Kementerian Kesehatan RI. hlm. 14', 'Belum divalidasi ahli gizi Nutriva', 'https://eprints.poltekkesadisutjipto.ac.id/id/eprint/1953/1/Share%20Buku%20Menu%20Makanan%20Lokal.pdf', NULL),
('Puding Kentang Ayam dan Telur', 'puding-kentang-ayam-telur', NULL, 6, 8, 'sedang', 'Mulai 2-3 sdm per makan, bertahap hingga 1/2 mangkok (125 ml) · resep untuk 3 porsi', '2-3 kali/hari makan utama, 1-2 kali/hari selingan', '{"per": "1 porsi", "calories": 95, "calories_kcal": 95, "protein_g": 4.0, "fat_g": 3.6, "carbs_g": 11.7, "iron_mg": 0.8, "iron_coverage_pct": 100.0, "texture": "Bubur kental / makanan lumat", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (USDA SR28), batas bawah"}}'::jsonb, ARRAY['100 g kentang, kukus dan haluskan','30 g (3 sdm) daging ayam cincang','10 g (1 butir) telur puyuh','15 g (1 buah) tahu kecil, potong dadu kecil','15 g (1,5 sdm) wortel parut','10 g (1 sdm) labu kuning','15 ml santan','1 batang sereh, 1 lembar daun salam','1 sdm minyak','50 ml air kaldu ayam','Bumbu halus: 2 siung bawang merah, 2 siung bawang putih','100 g (2 buah) jeruk, diambil sarinya']::text[], ARRAY['kedelai','telur']::text[], '[{"step": 1, "text": "Tumis bumbu halus dengan salam dan sereh, masukkan ayam, lalu sayuran dan tahu."}, {"step": 2, "text": "Tambahkan santan dan kaldu, matikan api, campurkan dengan kentang dan telur kocok."}, {"step": 3, "text": "Tuang ke wadah tahan panas yang diolesi minyak, kukus sekitar 20 menit."}, {"step": 4, "text": "Sajikan hangat dengan sari jeruk."}]'::jsonb, 'Kemenkes RI (2023). Makanan Lokal Bayi, Balita dan Ibu Hamil: Buku Resep. Jakarta: Kementerian Kesehatan RI. hlm. 15', 'Belum divalidasi ahli gizi Nutriva', 'https://eprints.poltekkesadisutjipto.ac.id/id/eprint/1953/1/Share%20Buku%20Menu%20Makanan%20Lokal.pdf', NULL),
('Nasi Tim Ikan Tuna Telur Puyuh', 'nasi-tim-ikan-tuna-telur-puyuh', NULL, 9, 11, 'premium', '1/2-3/4 mangkok ukuran 250 ml (125-200 ml) · resep untuk 3 porsi', '3-4 kali/hari makan utama, 1-2 kali/hari selingan', '{"per": "1 porsi", "calories": 120, "calories_kcal": 120, "protein_g": 4.6, "fat_g": 4.3, "carbs_g": 15.7, "iron_mg": 0.7, "iron_coverage_pct": 100.0, "texture": "Dicincang halus / makanan yang dapat dipegang", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (USDA SR28), batas bawah"}}'::jsonb, ARRAY['115 g (12 sdm) nasi putih','30 g (1 potong kecil) ikan tuna segar, haluskan','30 g (3 butir) telur puyuh','15 g wortel','10 g tomat','7,5 g (1,5 sdt) minyak kelapa','75 ml (1/3 gelas belimbing) kaldu ayam','50 g pepaya, haluskan (saus)','180 g (1 potong besar) semangka']::text[], ARRAY['ikan','telur']::text[], '[{"step": 1, "text": "Masukkan nasi, tuna, telur puyuh, dan minyak ke mangkuk tim, lalu tambahkan kaldu."}, {"step": 2, "text": "Masukkan wortel dan tomat, tim hingga matang."}, {"step": 3, "text": "Sajikan dengan saus pepaya dan semangka."}]'::jsonb, 'Kemenkes RI (2023). Makanan Lokal Bayi, Balita dan Ibu Hamil: Buku Resep. Jakarta: Kementerian Kesehatan RI. hlm. 19', 'Belum divalidasi ahli gizi Nutriva', 'https://eprints.poltekkesadisutjipto.ac.id/id/eprint/1953/1/Share%20Buku%20Menu%20Makanan%20Lokal.pdf', NULL),
('Nasi Tim Ayam Lele Cincang', 'nasi-tim-ayam-lele-cincang', NULL, 9, 11, 'sedang', '1/2-3/4 mangkok ukuran 250 ml (125-200 ml) · resep untuk 3 porsi', '3-4 kali/hari makan utama, 1-2 kali/hari selingan', '{"per": "1 porsi", "calories": 125, "calories_kcal": 125, "protein_g": 4.5, "fat_g": 4.9, "carbs_g": 15.7, "iron_mg": 0.4, "iron_coverage_pct": 100.0, "texture": "Dicincang halus / makanan yang dapat dipegang", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (USDA SR28), batas bawah"}}'::jsonb, ARRAY['100 g (10 sdm) nasi putih','30 g (3 sdm) daging ayam cincang','10 g (1 sdm) daging ikan lele','10 g (1 sdm) wortel','5 ml (1 sdt) minyak goreng','10 ml (1 sdm) santan kental','1,5 sdm bawang bombay, iris halus','200 ml kaldu ayam','180 g (1 potong besar) semangka']::text[], ARRAY['ikan']::text[], '[{"step": 1, "text": "Masukkan nasi, ayam, lele, bawang bombay, minyak, dan santan ke mangkuk tim."}, {"step": 2, "text": "Tambahkan kaldu dan wortel, masak hingga lunak."}, {"step": 3, "text": "Sajikan dengan semangka."}]'::jsonb, 'Kemenkes RI (2023). Makanan Lokal Bayi, Balita dan Ibu Hamil: Buku Resep. Jakarta: Kementerian Kesehatan RI. hlm. 20', 'Belum divalidasi ahli gizi Nutriva', 'https://eprints.poltekkesadisutjipto.ac.id/id/eprint/1953/1/Share%20Buku%20Menu%20Makanan%20Lokal.pdf', NULL),
('Mie Kukus Telur Puyuh', 'mie-kukus-telur-puyuh', NULL, 9, 11, 'premium', '1/2-3/4 mangkok ukuran 250 ml (125-200 ml) · resep untuk 3 porsi', '3-4 kali/hari makan utama, 1-2 kali/hari selingan', '{"per": "1 porsi", "calories": 135, "calories_kcal": 135, "protein_g": 5.1, "fat_g": 7.6, "carbs_g": 11.6, "iron_mg": null, "iron_coverage_pct": 100.0, "texture": "Dicincang halus / makanan yang dapat dipegang", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "tidak dihitung: ukuran porsi tercetak tidak konsisten dengan resep"}}'::jsonb, ARRAY['85 g (3 bungkus) mie instan batita atau mie keriting','60 g (6 butir) telur puyuh','50 g (5 sdm) wortel parut','50 g (5 sdm) keju parut','10 g (1 batang) bawang daun, iris','Minyak untuk menggoreng','Bumbu mie instan batita secukupnya','300 ml air','150 g (6 potong kecil) pepaya']::text[], ARRAY['gandum','susu','telur']::text[], '[{"step": 1, "text": "Rebus mie hingga lunak, tiriskan, campur dengan wortel, bawang daun, keju, dan bumbu."}, {"step": 2, "text": "Tuang ke wadah tahan panas yang diolesi minyak, selingi telur puyuh rebus, kukus 15 menit."}, {"step": 3, "text": "Sajikan langsung atau goreng hingga kekuningan; lengkapi dengan pepaya."}]'::jsonb, 'Kemenkes RI (2023). Makanan Lokal Bayi, Balita dan Ibu Hamil: Buku Resep. Jakarta: Kementerian Kesehatan RI. hlm. 21', 'Belum divalidasi ahli gizi Nutriva', 'https://eprints.poltekkesadisutjipto.ac.id/id/eprint/1953/1/Share%20Buku%20Menu%20Makanan%20Lokal.pdf', 'Mie instan batita tidak ada di katalog; estimasi besi memakai mie telur kering sebagai proksi. Energi 1/3 resep menurut estimasi bahan (237 kkal) jauh di atas nilai tercetak (135 kkal); porsi yang dimaksud buku kemungkinan lebih kecil dari 1/3 resep. Perlu review ahli gizi.'),
('Nasi Tim Ikan Telur Sayuran', 'nasi-tim-ikan-telur-sayuran', NULL, 9, 11, 'ekonomis', '1/2-3/4 mangkok ukuran 250 ml (125-200 ml) · resep untuk 3 porsi', '3-4 kali/hari makan utama, 1-2 kali/hari selingan', '{"per": "1 porsi", "calories": 117, "calories_kcal": 117, "protein_g": 4.8, "fat_g": 4.5, "carbs_g": 14.3, "iron_mg": 0.8, "iron_coverage_pct": 100.0, "texture": "Dicincang halus / makanan yang dapat dipegang", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (USDA SR28), batas bawah"}}'::jsonb, ARRAY['100 g (10 sdm) nasi putih','30 g (3 butir) telur puyuh, kocok','30 g (3 sdm) ikan kembung fillet','10 g (1 sdm) sawi hijau, iris','20 g (2 sdm) tomat, cincang','300 ml kaldu ayam','7,5 ml (1,5 sdt) minyak kelapa','180 g semangka']::text[], ARRAY['ikan','telur']::text[], '[{"step": 1, "text": "Masak kaldu, nasi, minyak, dan ikan hingga lunak menjadi bubur."}, {"step": 2, "text": "Masukkan sawi dan tomat, lalu telur puyuh kocok sambil diaduk hingga matang."}, {"step": 3, "text": "Sajikan dengan semangka."}]'::jsonb, 'Kemenkes RI (2023). Makanan Lokal Bayi, Balita dan Ibu Hamil: Buku Resep. Jakarta: Kementerian Kesehatan RI. hlm. 22', 'Belum divalidasi ahli gizi Nutriva', 'https://eprints.poltekkesadisutjipto.ac.id/id/eprint/1953/1/Share%20Buku%20Menu%20Makanan%20Lokal.pdf', 'Baris ''100 gr nasi'' tercetak dua kali; dihitung satu kali (100 g).'),
('Tim Bubur Manado Daging dan Udang', 'tim-bubur-manado-daging-udang', NULL, 9, 11, 'premium', '1/2-3/4 mangkok ukuran 250 ml (125-200 ml) · resep untuk 3 porsi', '3-4 kali/hari makan utama, 1-2 kali/hari selingan', '{"per": "1 porsi", "calories": 119, "calories_kcal": 119, "protein_g": 6.4, "fat_g": 4.4, "carbs_g": 13.5, "iron_mg": null, "iron_coverage_pct": 53.2, "texture": "Dicincang halus / makanan yang dapat dipegang", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "tidak dihitung: cakupan data bahan < 80%"}}'::jsonb, ARRAY['50 g (5 sdm) nasi putih','40 g (4 sdm) labu kuning, potong dadu','40 g (4 sdm) daging sapi cincang','30 g (3 ekor) udang kupas','20 g (2 sdm) jagung pipil','10 g (1 sdm) bayam','5 ml (1 sdt) minyak goreng','Garam secukupnya','10 g (1 batang) daun bawang, iris','100 ml kaldu daging','Bumbu halus: 1 siung bawang merah, 1 siung bawang putih','180 g (1 potong) buah naga']::text[], ARRAY['udang/krustasea']::text[], '[{"step": 1, "text": "Tumis bumbu halus hingga harum, masukkan daging dan udang hingga berubah warna."}, {"step": 2, "text": "Tambahkan kaldu, didihkan, lalu masukkan nasi, labu kuning, jagung, dan bayam."}, {"step": 3, "text": "Tambahkan daun bawang, masak hingga menyusut, beri sedikit garam, sajikan dengan buah naga."}]'::jsonb, 'Kemenkes RI (2023). Makanan Lokal Bayi, Balita dan Ibu Hamil: Buku Resep. Jakarta: Kementerian Kesehatan RI. hlm. 23', 'Belum divalidasi ahli gizi Nutriva', 'https://eprints.poltekkesadisutjipto.ac.id/id/eprint/1953/1/Share%20Buku%20Menu%20Makanan%20Lokal.pdf', NULL),
('Nasi Sup Telur Puyuh Bola Tahu Ayam', 'nasi-sup-telur-puyuh-bola-tahu-ayam', NULL, 12, 23, 'sedang', '3/4-1 mangkok ukuran 250 ml · resep untuk 3 porsi', '3-4 kali/hari makan utama, 1-2 kali/hari selingan', '{"per": "1 porsi", "calories": 260, "calories_kcal": 260, "protein_g": 10.4, "fat_g": 10.7, "carbs_g": 30.5, "iron_mg": 2.2, "iron_coverage_pct": 98.3, "texture": "Makanan keluarga, diiris bila perlu", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (USDA SR28), batas bawah"}}'::jsonb, ARRAY['150 g (15 sdm) nasi putih','45 g (1 potong kecil) tahu putih','60 g (5 sdm) daging ayam cincang','60 g (6 butir) telur puyuh rebus','30 g (3 sdm) wortel','30 g (3 sdm) jagung pipil kuning','30 g (3 sdm) brokoli','10 g (1 batang) seledri, iris','10 g (1 batang) daun bawang, iris','15 g (1,5 sdm) tepung tapioka','Garam, gula, merica secukupnya','10 g (1 sdm) bawang goreng','135 g (3 potong) melon']::text[], ARRAY['kedelai','telur']::text[], '[{"step": 1, "text": "Haluskan tahu, ayam, bumbu, dan tapioka; bentuk bola kecil lalu rebus hingga mengapung."}, {"step": 2, "text": "Masukkan wortel dan jagung, lalu brokoli dan telur puyuh."}, {"step": 3, "text": "Bumbui secukupnya, tambahkan daun bawang dan seledri."}, {"step": 4, "text": "Sajikan dengan nasi, taburan bawang goreng, dan melon."}]'::jsonb, 'Kemenkes RI (2023). Makanan Lokal Bayi, Balita dan Ibu Hamil: Buku Resep. Jakarta: Kementerian Kesehatan RI. hlm. 27', 'Belum divalidasi ahli gizi Nutriva', 'https://eprints.poltekkesadisutjipto.ac.id/id/eprint/1953/1/Share%20Buku%20Menu%20Makanan%20Lokal.pdf', NULL),
('Nasi Soto Ayam Kuah Kuning', 'nasi-soto-ayam-kuah-kuning', NULL, 12, 23, 'sedang', '3/4-1 mangkok ukuran 250 ml · resep untuk 3 porsi', '3-4 kali/hari makan utama, 1-2 kali/hari selingan', '{"per": "1 porsi", "calories": 263, "calories_kcal": 263, "protein_g": 9.5, "fat_g": 10.9, "carbs_g": 31.7, "iron_mg": 1.0, "iron_coverage_pct": 100.0, "texture": "Makanan keluarga, diiris bila perlu", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (USDA SR28), batas bawah"}}'::jsonb, ARRAY['150 g (15 sdm) nasi','100 g (2 potong) ayam dengan tulang','10 g (1 sdm) soun','60 g (6 butir) telur puyuh','30 g (3 sdm) tauge','10 g (1 sdm) minyak goreng','Daun salam, serai, daun jeruk, lengkuas, garam, gula, merica','Bumbu halus: kemiri, bawang merah, bawang putih, jahe, kunyit, jintan, ketumbar','Pelengkap: daun bawang, seledri, bawang goreng']::text[], ARRAY['telur']::text[], '[{"step": 1, "text": "Rebus ayam dengan serai, daun salam, daun jeruk, dan lengkuas."}, {"step": 2, "text": "Tumis bumbu halus hingga harum, masukkan ke rebusan; bumbui dan masak hingga ayam empuk, lalu suwir."}, {"step": 3, "text": "Sajikan dengan nasi, soun, tauge, telur puyuh, dan taburan pelengkap."}]'::jsonb, 'Kemenkes RI (2023). Makanan Lokal Bayi, Balita dan Ibu Hamil: Buku Resep. Jakarta: Kementerian Kesehatan RI. hlm. 28', 'Belum divalidasi ahli gizi Nutriva', 'https://eprints.poltekkesadisutjipto.ac.id/id/eprint/1953/1/Share%20Buku%20Menu%20Makanan%20Lokal.pdf', 'Ayam tercetak 100 g dengan tulang; berat bagian yang dapat dimakan tidak tercetak sehingga tidak ikut estimasi.'),
('Sup Telur Puyuh Ikan Air Tawar Labu Kuning', 'sup-telur-puyuh-ikan-nila-labu-kuning', NULL, 12, 23, 'ekonomis', '3/4-1 mangkok ukuran 250 ml · resep untuk 3 porsi', '3-4 kali/hari makan utama, 1-2 kali/hari selingan', '{"per": "1 porsi", "calories": 261, "calories_kcal": 261, "protein_g": 13.6, "fat_g": 9.1, "carbs_g": 31.2, "iron_mg": 1.9, "iron_coverage_pct": 98.5, "texture": "Makanan keluarga, diiris bila perlu", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (USDA SR28), batas bawah"}}'::jsonb, ARRAY['150 g (15 sdm) nasi putih','70 g (7 sdm) kentang, potong dadu','50 g (5 sdm) labu kuning, potong dadu','120 g (12 sdm) ikan nila kukus, suwir','60 g (6 butir) telur puyuh rebus','15 g (3 sdt) kacang merah','45 g (4,5 sdm) tomat, potong dadu','10 g (1 batang) bawang daun','5 g bawang merah goreng, 5 g bawang putih goreng','150 ml kaldu ayam','Garam, gula, merica secukupnya','150 g (6 potong) pepaya']::text[], ARRAY['ikan','telur']::text[], '[{"step": 1, "text": "Didihkan kaldu, masukkan kentang, kacang merah, dan labu kuning hingga setengah matang."}, {"step": 2, "text": "Tambahkan ikan, bawang goreng, tomat, bawang daun, dan telur puyuh; bumbui secukupnya."}, {"step": 3, "text": "Sajikan dengan nasi dan pepaya."}]'::jsonb, 'Kemenkes RI (2023). Makanan Lokal Bayi, Balita dan Ibu Hamil: Buku Resep. Jakarta: Kementerian Kesehatan RI. hlm. 29', 'Belum divalidasi ahli gizi Nutriva', 'https://eprints.poltekkesadisutjipto.ac.id/id/eprint/1953/1/Share%20Buku%20Menu%20Makanan%20Lokal.pdf', NULL),
('Nasi Ikan Kuah Kuning', 'nasi-ikan-kuah-kuning', NULL, 12, 23, 'ekonomis', '3/4-1 mangkok ukuran 250 ml · resep untuk 3 porsi', '3-4 kali/hari makan utama, 1-2 kali/hari selingan', '{"per": "1 porsi", "calories": 267, "calories_kcal": 267, "protein_g": 28.5, "fat_g": 10.7, "carbs_g": 14.2, "iron_mg": 1.3, "iron_coverage_pct": 100.0, "texture": "Makanan keluarga, diiris bila perlu", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (USDA SR28), batas bawah"}}'::jsonb, ARRAY['150 g (15 sdm) nasi','360 g (3 ekor) ikan kembung','75 g (7,5 sdm) labu siam','75 g (7,5 sdm) tempe','60 g (1 buah besar) tomat','15 ml (1,5 sdm) minyak goreng','35 ml (3,5 sdm) santan','Daun salam, sereh, laos, garam, gula, 2 buah jeruk nipis, 750 ml air','Bumbu halus: bawang merah, bawang putih, kemiri, jahe, kunyit','270 g semangka']::text[], ARRAY['ikan','kedelai']::text[], '[{"step": 1, "text": "Lumuri ikan dengan garam dan jeruk nipis, bilas, lalu goreng hingga matang."}, {"step": 2, "text": "Tumis bumbu halus dengan sereh, salam, dan laos; tambahkan air, labu siam, dan tempe hingga matang."}, {"step": 3, "text": "Masukkan santan, ikan, dan tomat; bumbui secukupnya."}, {"step": 4, "text": "Sajikan dengan nasi dan semangka."}]'::jsonb, 'Kemenkes RI (2023). Makanan Lokal Bayi, Balita dan Ibu Hamil: Buku Resep. Jakarta: Kementerian Kesehatan RI. hlm. 30', 'Belum divalidasi ahli gizi Nutriva', 'https://eprints.poltekkesadisutjipto.ac.id/id/eprint/1953/1/Share%20Buku%20Menu%20Makanan%20Lokal.pdf', 'Ikan kembung tercetak 360 g (3 ekor), berat utuh termasuk tulang; tidak ikut estimasi besi.'),
('Nugget Tempe Ayam Sayuran', 'nugget-tempe-ayam-sayuran', NULL, 12, 23, 'premium', 'Resep untuk 3 porsi', 'Selingan: 1-2 kali/hari', '{"per": "1 porsi", "calories": 191, "calories_kcal": 191, "protein_g": 10.5, "fat_g": 9.0, "carbs_g": 17.0, "iron_mg": null, "iron_coverage_pct": 99.0, "texture": "Makanan keluarga, diiris bila perlu", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "tidak dihitung: ukuran porsi tercetak tidak konsisten dengan resep"}}'::jsonb, ARRAY['200 g tempe, potong kecil, kukus','100 g daging ayam cincang, haluskan','100 g (2 butir) telur ayam, kocok','50 g (5 sdm) wortel','50 g (5 sdm) keju parut','10 g (1 batang) bawang daun, iris halus','10 g bawang goreng halus','10 g bawang putih halus','20 g (2 sdm) tepung terigu (adonan)','20 g (2 sdm) tepung tapioka','30 g (3 sdm) tepung terigu (pelapis)','100 g (10 sdm) tepung panir','100 ml air; minyak untuk menggoreng','270 g semangka']::text[], ARRAY['gandum','kedelai','susu','telur']::text[], '[{"step": 1, "text": "Campur semua bahan adonan, tuang ke loyang berolesi minyak, kukus 30 menit."}, {"step": 2, "text": "Setelah dingin potong-potong, celup ke larutan terigu lalu gulingkan di tepung panir."}, {"step": 3, "text": "Dinginkan sebentar di kulkas, lalu goreng hingga matang. Sajikan dengan semangka."}]'::jsonb, 'Kemenkes RI (2023). Makanan Lokal Bayi, Balita dan Ibu Hamil: Buku Resep. Jakarta: Kementerian Kesehatan RI. hlm. 31', 'Belum divalidasi ahli gizi Nutriva', 'https://eprints.poltekkesadisutjipto.ac.id/id/eprint/1953/1/Share%20Buku%20Menu%20Makanan%20Lokal.pdf', 'Energi 1/3 resep menurut estimasi bahan (539 kkal) jauh di atas nilai tercetak (191 kkal); porsi yang dimaksud buku kemungkinan lebih kecil dari 1/3 resep. Perlu review ahli gizi.'),
('Nasi Bakar Ayam Santan', 'nasi-bakar-ayam-santan', NULL, 24, 59, 'premium', '1 porsi resep (lihat bahan) · resep untuk 3 porsi', '3-4 kali/hari makan utama, 1-2 kali/hari selingan', '{"per": "1 porsi", "calories": 421, "calories_kcal": 421, "protein_g": 18.2, "fat_g": 18.2, "carbs_g": 46.1, "iron_mg": 2.5, "iron_coverage_pct": 98.8, "texture": "Makanan keluarga", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (USDA SR28), batas bawah"}}'::jsonb, ARRAY['150 g (15 sdm) beras putih','20 g (2 sdm) minyak goreng','10 g (1 sdm) margarin','5 g bawang putih goreng, 5 g bawang merah goreng','120 g (12 sdm) fillet dada ayam, potong kotak','60 g (3 potong) tahu, potong kotak','60 g (6 ekor) udang','30 g (3 sdm) daun bayam','30 g (3 sdm) wortel','50 ml (5 sdm) santan kental','Bumbu: bawang merah, bawang putih, ketumbar, kemiri, jinten, jahe, daun jeruk, salam, sereh, pandan, garam','300 g pepaya']::text[], ARRAY['kedelai','udang/krustasea']::text[], '[{"step": 1, "text": "Masak beras dengan bumbu gurih (margarin, bawang goreng, daun-daunan) hingga menjadi nasi."}, {"step": 2, "text": "Tumis bumbu halus dengan jahe, salam, sereh, daun jeruk; masak ayam dan udang, tambahkan santan, tahu, wortel, bayam."}, {"step": 3, "text": "Bungkus nasi dan isian dengan daun pisang, kukus 10 menit, lalu panggang 10 menit."}, {"step": 4, "text": "Sajikan dengan pepaya."}]'::jsonb, 'Kemenkes RI (2023). Makanan Lokal Bayi, Balita dan Ibu Hamil: Buku Resep. Jakarta: Kementerian Kesehatan RI. hlm. 35', 'Belum divalidasi ahli gizi Nutriva', 'https://eprints.poltekkesadisutjipto.ac.id/id/eprint/1953/1/Share%20Buku%20Menu%20Makanan%20Lokal.pdf', NULL),
('Nasi Sup Tabas Udang Sayur', 'nasi-sup-tabas-udang-sayur', NULL, 24, 59, 'premium', '1 porsi resep (lihat bahan) · resep untuk 3 porsi', '3-4 kali/hari makan utama, 1-2 kali/hari selingan', '{"per": "1 porsi", "calories": 537, "calories_kcal": 537, "protein_g": 23.4, "fat_g": 18.9, "carbs_g": 68.3, "iron_mg": 3.5, "iron_coverage_pct": 97.6, "texture": "Makanan keluarga", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (USDA SR28), batas bawah"}}'::jsonb, ARRAY['300 g (3 centong) nasi putih','150 g (15 sdm) ikan tenggiri cincang','1 butir putih telur','20 g (2 sdm) tepung tapioka','90 g (9 sdm) tahu','20 g (2 batang) daun bawang','10 g bawang goreng','10 g saos tiram, 5 g kecap ikan','10 g (1 sdm) minyak wijen','5 g garam, 2,5 g merica','90 g (9 sdm) udang rebus','500 ml air kaldu udang','60 g (6 sdm) pokcoy','60 g (6 sdm) soun, rendam','60 g (6 sdm) wortel','10 g (1 batang) seledri','10 g (1 sdm) minyak untuk menumis','Bumbu halus: 2 siung bawang merah, 1 siung bawang putih; 1 cm jahe','540 g semangka']::text[], ARRAY['ikan','kedelai','moluska','telur','udang/krustasea','wijen']::text[], '[{"step": 1, "text": "Campur ikan, tapioka, bumbu, dan putih telur hingga bisa dibentuk; isikan ke tahu yang dilubangi, kukus 15-20 menit."}, {"step": 2, "text": "Tumis bumbu halus, tambahkan kaldu udang, udang, wortel, dan bumbu."}, {"step": 3, "text": "Masukkan tahu tabas, pokcoy, dan soun; siramkan kuah ke mangkuk berisi nasi."}, {"step": 4, "text": "Sajikan dengan semangka."}]'::jsonb, 'Kemenkes RI (2023). Makanan Lokal Bayi, Balita dan Ibu Hamil: Buku Resep. Jakarta: Kementerian Kesehatan RI. hlm. 37', 'Belum divalidasi ahli gizi Nutriva', 'https://eprints.poltekkesadisutjipto.ac.id/id/eprint/1953/1/Share%20Buku%20Menu%20Makanan%20Lokal.pdf', NULL),
('Nasi Masak Ayam Kecap Sayur', 'nasi-masak-ayam-kecap-sayur', NULL, 24, 59, 'sedang', '1 porsi resep (lihat bahan) · resep untuk 3 porsi', '3-4 kali/hari makan utama, 1-2 kali/hari selingan', '{"per": "1 porsi", "calories": 424, "calories_kcal": 424, "protein_g": 22.9, "fat_g": 18.1, "carbs_g": 42.4, "iron_mg": 4.1, "iron_coverage_pct": 96.3, "texture": "Makanan keluarga", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (USDA SR28), batas bawah"}}'::jsonb, ARRAY['300 g (3 centong) nasi putih','120 g (12 sdm) dada ayam fillet, iris tipis','60 g (6 butir) telur puyuh rebus','150 g (2 buah besar) tahu putih, potong dadu','100 g (10 sdm) pakcoy, potong 3 cm','40 g (4 sdm) kecap manis','50 ml (5 sdm) air','20 g (2 sdm) minyak','1 siung bawang putih, 1/4 bawang bombay, daun bawang','Garam, gula, merica secukupnya','300 g (3 buah) jeruk']::text[], ARRAY['kedelai','telur']::text[], '[{"step": 1, "text": "Tumis bawang putih lalu bawang bombay hingga harum, masukkan ayam hingga berubah warna."}, {"step": 2, "text": "Tambahkan tahu, telur puyuh, pakcoy, kecap manis, bumbu, dan air; masak hingga matang."}, {"step": 3, "text": "Taburi daun bawang, sajikan dengan nasi dan jeruk."}]'::jsonb, 'Kemenkes RI (2023). Makanan Lokal Bayi, Balita dan Ibu Hamil: Buku Resep. Jakarta: Kementerian Kesehatan RI. hlm. 39', 'Belum divalidasi ahli gizi Nutriva', 'https://eprints.poltekkesadisutjipto.ac.id/id/eprint/1953/1/Share%20Buku%20Menu%20Makanan%20Lokal.pdf', NULL),
('Bola-bola Nasi Rabuk Ikan', 'bola-bola-nasi-rabuk-ikan', NULL, 24, 59, 'ekonomis', '1 porsi resep (lihat bahan) · resep untuk 3 porsi', '3-4 kali/hari makan utama, 1-2 kali/hari selingan', '{"per": "1 porsi", "calories": 468, "calories_kcal": 468, "protein_g": 14.4, "fat_g": 17.4, "carbs_g": 63.4, "iron_mg": null, "iron_coverage_pct": 52.8, "texture": "Makanan keluarga", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "tidak dihitung: cakupan data bahan < 80%"}}'::jsonb, ARRAY['150 g beras, dimasak menjadi nasi','40 g (4 sdm) minyak sayur','18 g (2 sdm) buncis, iris','10 g (1 sdm) wortel, cincang','45 g (4,5 sdm) jagung pipil, cincang kasar','50 g (5 sdm) tepung terigu','30 g (1/2 butir) telur ayam','50 g (5 sdm) rabuk ikan','10 g (2 sdm) bawang bombay iris','5 g bawang putih goreng, 5 g bawang merah goreng','Daun bawang, lada, garam, kaldu jamur secukupnya','Pelapis: 50 g (1 butir) telur ayam, tepung roti secukupnya','300 g buah naga']::text[], ARRAY['gandum','ikan','telur']::text[], '[{"step": 1, "text": "Tumis bawang bombay lalu sayuran hingga setengah matang."}, {"step": 2, "text": "Campur dengan nasi, terigu, telur, bawang goreng, dan bumbu hingga kalis."}, {"step": 3, "text": "Pipihkan adonan, isi dengan rabuk ikan, bentuk bulat; lapisi terigu, telur kocok, dan tepung roti."}, {"step": 4, "text": "Diamkan minimal 1 jam lalu goreng. Sajikan dengan buah naga."}]'::jsonb, 'Kemenkes RI (2023). Makanan Lokal Bayi, Balita dan Ibu Hamil: Buku Resep. Jakarta: Kementerian Kesehatan RI. hlm. 40', 'Belum divalidasi ahli gizi Nutriva', 'https://eprints.poltekkesadisutjipto.ac.id/id/eprint/1953/1/Share%20Buku%20Menu%20Makanan%20Lokal.pdf', NULL),
('Bubur Ikan Jagung', 'bubur-ikan-jagung', NULL, 6, 8, 'ekonomis', 'Mulai 2-3 sdm per makan, bertahap hingga 1/2 mangkok (125 ml) · resep untuk 1 porsi', '2-3 kali/hari makan utama, 1-2 kali/hari selingan', '{"per": "1 porsi", "calories": 191, "calories_kcal": 190.6, "protein_g": 7.5, "fat_g": 6.8, "carbs_g": 24.9, "iron_mg": 1.1, "iron_coverage_pct": 87.5, "texture": "Bubur kental / makanan lumat", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (USDA SR28), batas bawah"}}'::jsonb, ARRAY['15 g (1,5 sdm) tepung jagung','10 g (1 sdm) ikan','5 g (1 sdt) tempe','25 g pisang kepok','20 g daun kangkung','1 sdt minyak kelapa','Air matang secukupnya']::text[], ARRAY['ikan','kedelai']::text[], '[{"step": 1, "text": "Rebus ikan, tempe, dan pisang hingga matang, tambahkan kangkung, lalu saring."}, {"step": 2, "text": "Larutkan tepung jagung dengan sedikit air, masak bersama air dan minyak hingga kental."}, {"step": 3, "text": "Campurkan hasil saringan ke bubur jagung dan sajikan."}]'::jsonb, 'Kemenkes RI (2022). Buku Resep Makanan Lokal Balita dan Ibu Hamil. Jakarta: Ditjen Kesehatan Masyarakat, Direktorat Gizi dan KIA. hlm. 6', 'Belum divalidasi ahli gizi Nutriva', 'https://pkmpati2.patikab.go.id/data_bansos/file/Buku_Resep_Makanan_Lokal_Balita_dan_Ibu_Hamil.pdf', 'Jumlah porsi tidak tercetak; nilai gizi dianggap untuk 1 resep = 1 porsi. Jenis ikan tidak disebut.'),
('Nasi Tim Ikan Telur Puyuh Wortel', 'nasi-tim-ikan-telur-puyuh-wortel', NULL, 9, 11, 'ekonomis', '1/2-3/4 mangkok ukuran 250 ml (125-200 ml) · resep untuk 1 porsi', '3-4 kali/hari makan utama, 1-2 kali/hari selingan', '{"per": "1 porsi", "calories": 203, "calories_kcal": 202.7, "protein_g": 7.5, "fat_g": 7.3, "carbs_g": 26.7, "iron_mg": 0.8, "iron_coverage_pct": 85.2, "texture": "Dicincang halus / makanan yang dapat dipegang", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (USDA SR28), batas bawah"}}'::jsonb, ARRAY['25 g beras','20 g ikan segar','1 butir telur puyuh','15 g wortel','10 g tomat','5 g (1 sdt) minyak kelapa','75 ml (1/3 gelas belimbing) kaldu','50 g pepaya']::text[], ARRAY['ikan','telur']::text[], '[{"step": 1, "text": "Masukkan beras, ikan, telur puyuh, dan minyak ke mangkuk tim, tambahkan kaldu, tim hingga matang."}, {"step": 2, "text": "Masukkan wortel dan tomat, tim kembali hingga lunak."}, {"step": 3, "text": "Sajikan dengan saus pepaya."}]'::jsonb, 'Kemenkes RI (2022). Buku Resep Makanan Lokal Balita dan Ibu Hamil. Jakarta: Ditjen Kesehatan Masyarakat, Direktorat Gizi dan KIA. hlm. 7', 'Belum divalidasi ahli gizi Nutriva', 'https://pkmpati2.patikab.go.id/data_bansos/file/Buku_Resep_Makanan_Lokal_Balita_dan_Ibu_Hamil.pdf', 'Jumlah porsi tidak tercetak; dianggap 1 porsi. Jenis ikan tidak disebut.'),
('Tim Ikan Menado', 'tim-ikan-menado', NULL, 12, 23, 'ekonomis', '3/4-1 mangkok ukuran 250 ml · resep untuk 1 porsi', '3-4 kali/hari makan utama, 1-2 kali/hari selingan', '{"per": "1 porsi", "calories": 234, "calories_kcal": 234.3, "protein_g": 10.7, "fat_g": 8.5, "carbs_g": 28.8, "iron_mg": 1.4, "iron_coverage_pct": 87.5, "texture": "Makanan keluarga, diiris bila perlu", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (USDA SR28), batas bawah"}}'::jsonb, ARRAY['60 g jagung muda pipil','60 labu kuning (satuan tidak tercetak)','30 ikan segar (satuan tidak tercetak)','10 g (1 sdm) telur ayam','15 g daun kangkung','10 g tomat','50 pisang ambon (satuan tidak tercetak)','5 g (1 sdt) minyak kelapa','100 ml kaldu ayam']::text[], ARRAY['ikan','telur']::text[], '[{"step": 1, "text": "Susun jagung, labu kuning, ikan, dan telur di mangkuk tim, tambahkan kaldu."}, {"step": 2, "text": "Masukkan pisang, kangkung, tomat, dan minyak; tim hingga matang."}]'::jsonb, 'Kemenkes RI (2022). Buku Resep Makanan Lokal Balita dan Ibu Hamil. Jakarta: Ditjen Kesehatan Masyarakat, Direktorat Gizi dan KIA. hlm. 10', 'Belum divalidasi ahli gizi Nutriva', 'https://pkmpati2.patikab.go.id/data_bansos/file/Buku_Resep_Makanan_Lokal_Balita_dan_Ibu_Hamil.pdf', 'Satuan labu kuning (60), ikan segar (30), dan pisang ambon (50) tidak tercetak; diasumsikan gram. Jumlah porsi tidak tercetak.'),
('Nugget Sayuran', 'nugget-sayuran', NULL, 12, 23, 'sedang', 'Resep untuk 2 porsi', 'Selingan: 1-2 kali/hari', '{"per": "1 porsi", "calories": 270, "calories_kcal": 270.5, "protein_g": 10.6, "fat_g": 15.7, "carbs_g": 21.7, "iron_mg": 1.1, "iron_coverage_pct": 100.0, "texture": "Makanan keluarga, diiris bila perlu", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (USDA SR28), batas bawah"}}'::jsonb, ARRAY['150 g ubi jalar merah, rebus dan haluskan','50 g (1 butir) telur ayam, kocok','30 g daging ayam','1 cangkir bayam, cincang kasar','20 g (2 sdm) wortel, parut kasar','3 siung bawang putih, cincang','Garam secukupnya; minyak untuk menggoreng']::text[], ARRAY['telur']::text[], '[{"step": 1, "text": "Campur bayam, wortel, ubi, telur, ayam, bawang putih, dan garam hingga rata."}, {"step": 2, "text": "Bentuk pipih bulat, celupkan ke kocokan telur, lalu goreng hingga matang dan tiriskan."}]'::jsonb, 'Kemenkes RI (2022). Buku Resep Makanan Lokal Balita dan Ibu Hamil. Jakarta: Ditjen Kesehatan Masyarakat, Direktorat Gizi dan KIA. hlm. 13', 'Belum divalidasi ahli gizi Nutriva', 'https://pkmpati2.patikab.go.id/data_bansos/file/Buku_Resep_Makanan_Lokal_Balita_dan_Ibu_Hamil.pdf', NULL),
('Nasi Ayam Katsu, Tumis Sayuran + Melon', 'nasi-ayam-katsu-tumis-sayur-melon', NULL, 24, 59, 'sedang', '1 porsi resep (lihat bahan) · resep untuk 3 porsi', '3-4 kali/hari makan utama, 1-2 kali/hari selingan', '{"per": "1 porsi", "calories": 403, "calories_kcal": 403.3, "protein_g": 12.0, "fat_g": 17.7, "carbs_g": 49.0, "iron_mg": 3.3, "iron_coverage_pct": 100.0, "texture": "Makanan keluarga", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (USDA SR28), batas bawah"}}'::jsonb, ARRAY['225 g nasi putih','75 g ayam fillet','10 sdm tepung terigu','10 g tepung jagung','50 g tepung roti','1/2 butir telur ayam','30 g wortel','30 g buncis','30 g jagung pipil kuning','30 g bawang bombay','30 g bawang putih','Garam, gula, merica, air secukupnya','3 potong melon']::text[], ARRAY['gandum','telur']::text[], '[{"step": 1, "text": "Pipihkan ayam, beri garam dan merica, lapisi adonan tepung, telur, lalu tepung roti; goreng hingga kuning keemasan."}, {"step": 2, "text": "Tumis bawang, masukkan wortel, jagung, buncis, sedikit air, garam, dan gula."}, {"step": 3, "text": "Sajikan dengan nasi dan melon."}]'::jsonb, 'Kemenkes RI (2022). Buku Resep Makanan Lokal Balita dan Ibu Hamil. Jakarta: Ditjen Kesehatan Masyarakat, Direktorat Gizi dan KIA. hlm. 14', 'Belum divalidasi ahli gizi Nutriva', 'https://pkmpati2.patikab.go.id/data_bansos/file/Buku_Resep_Makanan_Lokal_Balita_dan_Ibu_Hamil.pdf', 'Tepung terigu tercetak ''10 sdm'' (dihitung 100 g dengan 1 sdm = 10 g). Minyak goreng tidak tercetak.'),
('Nasi Bakar Ikan Tongkol + Pepaya', 'nasi-bakar-ikan-tongkol-pepaya', NULL, 24, 59, 'ekonomis', '1 porsi resep (lihat bahan) · resep untuk 2 porsi', '3-4 kali/hari makan utama, 1-2 kali/hari selingan', '{"per": "1 porsi", "calories": 360, "calories_kcal": 360.2, "protein_g": 17.1, "fat_g": 10.4, "carbs_g": 49.1, "iron_mg": 2.8, "iron_coverage_pct": 100.0, "texture": "Makanan keluarga", "basis": {"energy_protein_fat": "estimasi dari bahan (USDA SR28); nilai tercetak tidak plausibel", "carbs": "estimasi dari bahan (USDA SR28)", "iron": "estimasi dari bahan bergramasi (USDA SR28), batas bawah"}}'::jsonb, ARRAY['330 g nasi putih','90 g ikan tongkol kukus','15 g bayam','45 g tahu, dihancurkan','70 ml santan','Jahe, lengkuas, serai, daun salam, kemangi, garam, gula','Bumbu halus: 2 siung bawang merah, 2 siung bawang putih, 2 butir kemiri','Daun pisang; minyak untuk menumis','Pepaya']::text[], ARRAY['ikan','kedelai']::text[], '[{"step": 1, "text": "Tumis bumbu halus dengan daun salam, serai, dan lengkuas; masukkan tongkol suwir, tahu, santan, dan bayam."}, {"step": 2, "text": "Bungkus nasi dengan daun pisang, beri isian dan kemangi."}, {"step": 3, "text": "Bakar atau kukus hingga daun kering. Sajikan dengan pepaya."}]'::jsonb, 'Kemenkes RI (2022). Buku Resep Makanan Lokal Balita dan Ibu Hamil. Jakarta: Ditjen Kesehatan Masyarakat, Direktorat Gizi dan KIA. hlm. 15', 'Belum divalidasi ahli gizi Nutriva', 'https://pkmpati2.patikab.go.id/data_bansos/file/Buku_Resep_Makanan_Lokal_Balita_dan_Ibu_Hamil.pdf', 'Nilai gizi tercetak identik dengan Nugget Sayuran (hlm. 13); kemungkinan salah cetak sehingga tidak dipakai. Jumlah pepaya tidak tercetak.'),
('Pepes Tahu', 'pepes-tahu', NULL, 24, 59, 'sedang', 'Resep untuk 2 porsi', 'Selingan: 1-2 kali/hari', '{"per": "1 porsi", "calories": 305, "calories_kcal": 304.7, "protein_g": 17.9, "fat_g": 17.0, "carbs_g": 20.0, "iron_mg": 8.9, "iron_coverage_pct": 97.0, "texture": "Makanan keluarga", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (USDA SR28), batas bawah"}}'::jsonb, ARRAY['300 g tahu putih, haluskan','100 g wortel, parut','2 siung bawang putih, 3 siung bawang merah, iris','10 g daging ayam','50 g (1 butir) telur ayam','15 g kerupuk aci','10 g daun bawang','5 g margarin','15 g (1 sdm) tepung tapioka','Daun pisang']::text[], ARRAY['kedelai','telur']::text[], '[{"step": 1, "text": "Campur tahu halus, wortel, bawang, ayam, kerupuk aci yang direndam, tapioka, dan telur kocok."}, {"step": 2, "text": "Ambil 2 sdm adonan, bungkus dengan daun pisang."}, {"step": 3, "text": "Kukus hingga matang."}]'::jsonb, 'Kemenkes RI (2022). Buku Resep Makanan Lokal Balita dan Ibu Hamil. Jakarta: Ditjen Kesehatan Masyarakat, Direktorat Gizi dan KIA. hlm. 16', 'Belum divalidasi ahli gizi Nutriva', 'https://pkmpati2.patikab.go.id/data_bansos/file/Buku_Resep_Makanan_Lokal_Balita_dan_Ibu_Hamil.pdf', NULL),
('Omelet Mie Ceria', 'omelet-mie-ceria', NULL, 24, 59, 'sedang', 'Resep untuk 2 porsi', 'Selingan: 1-2 kali/hari', '{"per": "1 porsi", "calories": 336, "calories_kcal": 335.9, "protein_g": 15.9, "fat_g": 21.7, "carbs_g": 19.2, "iron_mg": 2.2, "iron_coverage_pct": 100.0, "texture": "Makanan keluarga", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (USDA SR28), batas bawah"}}'::jsonb, ARRAY['50 g daging ayam giling','100 g (2 butir) telur ayam','40 g sawi hijau, iris tipis','50 g tauge','10 g (1 batang) daun bawang, iris tipis','7,5 ml (1,5 sdt) kecap asin','3 g (1/2 sdt) merica','50 g wortel','20 ml (2 sdm) minyak','40 g mie kering']::text[], ARRAY['gandum','kedelai','telur']::text[], '[{"step": 1, "text": "Rebus mie hingga matang dan tiriskan, lalu aduk dengan semua bahan kecuali minyak."}, {"step": 2, "text": "Panaskan minyak di wajan antilengket, masak adonan dalam dua bagian hingga kedua sisi matang."}, {"step": 3, "text": "Potong sesuai selera dan sajikan hangat."}]'::jsonb, 'Kemenkes RI (2022). Buku Resep Makanan Lokal Balita dan Ibu Hamil. Jakarta: Ditjen Kesehatan Masyarakat, Direktorat Gizi dan KIA. hlm. 17', 'Belum divalidasi ahli gizi Nutriva', 'https://pkmpati2.patikab.go.id/data_bansos/file/Buku_Resep_Makanan_Lokal_Balita_dan_Ibu_Hamil.pdf', NULL),
('Roti Goreng isi Ragout Ayam Sayuran', 'roti-goreng-isi-ragout-ayam-sayuran', NULL, 24, 59, 'sedang', 'Resep untuk 5 porsi', 'Selingan: 1-2 kali/hari', '{"per": "1 porsi", "calories": 319, "calories_kcal": 319.2, "protein_g": 16.8, "fat_g": 12.0, "carbs_g": 36.0, "iron_mg": 0.9, "iron_coverage_pct": 100.0, "texture": "Makanan keluarga", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "estimasi dari bahan bergramasi (USDA SR28), batas bawah"}}'::jsonb, ARRAY['300 ml susu cair','10 lembar roti tawar, potong segitiga','1/2 buah bawang bombay, cincang halus','1 sdt gula pasir, 1 sdt garam','7,5 g margarin','160 g daging ayam rebus','60 g wortel, cincang','30 g buncis, potong kecil','3 sdm tepung terigu','1 butir telur ayam','1/2 sdm seledri; tepung panir secukupnya']::text[], ARRAY['gandum','susu','telur']::text[], '[{"step": 1, "text": "Tumis bawang bombay dengan margarin, tambahkan terigu, lalu tuang susu sedikit demi sedikit sambil diaduk."}, {"step": 2, "text": "Masukkan wortel, buncis, ayam, dan bumbu hingga mengental menjadi ragout."}, {"step": 3, "text": "Olesi roti dengan susu, beri isian, tutup roti lain; celup ke telur dan tepung panir, lalu goreng."}]'::jsonb, 'Kemenkes RI (2022). Buku Resep Makanan Lokal Balita dan Ibu Hamil. Jakarta: Ditjen Kesehatan Masyarakat, Direktorat Gizi dan KIA. hlm. 18', 'Belum divalidasi ahli gizi Nutriva', 'https://pkmpati2.patikab.go.id/data_bansos/file/Buku_Resep_Makanan_Lokal_Balita_dan_Ibu_Hamil.pdf', 'Daging ayam tercetak dalam keadaan rebus; estimasi memakai komposisi ayam mentah sehingga cenderung rendah. Berat roti tawar tidak tercetak.'),
('Stick Ikan dan Sayur Renyah', 'stick-ikan-sayur-renyah', NULL, 24, 59, 'ekonomis', 'Resep untuk 2 porsi', 'Selingan: 1-2 kali/hari', '{"per": "1 porsi", "calories": 315, "calories_kcal": 315.2, "protein_g": 15.3, "fat_g": 19.2, "carbs_g": 20.3, "iron_mg": null, "iron_coverage_pct": 43.4, "texture": "Makanan keluarga", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "tidak dihitung: cakupan data bahan < 80%"}}'::jsonb, ARRAY['100 g fillet ikan segar','40 g (4 sdm) wortel','25 g kangkung','1 butir telur ayam','50 g (5 sdm) tepung bumbu serbaguna','Air es secukupnya; minyak untuk menggoreng']::text[], ARRAY['gandum','ikan','telur']::text[], '[{"step": 1, "text": "Cincang halus wortel dan kangkung, campur dengan tepung dan telur."}, {"step": 2, "text": "Tambahkan air es sedikit demi sedikit hingga adonan mengental."}, {"step": 3, "text": "Celupkan potongan fillet ikan ke adonan, goreng hingga matang."}]'::jsonb, 'Kemenkes RI (2022). Buku Resep Makanan Lokal Balita dan Ibu Hamil. Jakarta: Ditjen Kesehatan Masyarakat, Direktorat Gizi dan KIA. hlm. 20', 'Belum divalidasi ahli gizi Nutriva', 'https://pkmpati2.patikab.go.id/data_bansos/file/Buku_Resep_Makanan_Lokal_Balita_dan_Ibu_Hamil.pdf', 'Jenis ikan tidak disebut. Tepung bumbu serbaguna tidak ada di katalog.'),
('Ikan Bakar Balita', 'ikan-bakar-balita', NULL, 24, 59, 'ekonomis', 'Resep untuk 4 porsi', 'Lauk pendamping makan utama', '{"per": "1 porsi", "calories": 141, "calories_kcal": 140.6, "protein_g": 19.7, "fat_g": 5.6, "carbs_g": 2.8, "iron_mg": null, "iron_coverage_pct": 0.0, "texture": "Makanan keluarga", "basis": {"energy_protein_fat": "tercetak (Kemenkes)", "carbs": "turunan Atwater dari nilai tercetak", "iron": "tidak dihitung: cakupan data bahan < 80%"}}'::jsonb, ARRAY['1 ekor ikan air tawar','2 buah jeruk nipis','Bumbu halus: 1 siung bawang putih, 5 butir bawang merah, 1/2 sdm ketumbar, 1 cm jahe, 1 cm kunyit','Garam secukupnya (boleh tidak dipakai)']::text[], ARRAY['ikan']::text[], '[{"step": 1, "text": "Lumuri ikan dengan air jeruk nipis."}, {"step": 2, "text": "Bakar di atas bara sambil dioles bumbu halus hingga matang, lalu sajikan."}]'::jsonb, 'Kemenkes RI (2022). Buku Resep Makanan Lokal Balita dan Ibu Hamil. Jakarta: Ditjen Kesehatan Masyarakat, Direktorat Gizi dan KIA. hlm. 22', 'Belum divalidasi ahli gizi Nutriva', 'https://pkmpati2.patikab.go.id/data_bansos/file/Buku_Resep_Makanan_Lokal_Balita_dan_Ibu_Hamil.pdf', 'Berat ikan tidak tercetak (1 ekor ikan air tawar).')
